const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path');
const {normalize,resultPath,lock}=require('../src/cli.cjs');
test('job paths resolve from JSON folder, including nested cell images',()=>{const base=path.resolve('jobs'),req=normalize({schema:1,action:'create',output:'가정 통신문.hwpx',blocks:[{type:'table',rows:[[{blocks:[{type:'image',path:'사진.png'}]}]]}]},base);assert.equal(req.path,path.join(base,'가정 통신문.hwpx'));assert.equal(req.blocks[0].rows[0][0].blocks[0].path,path.join(base,'사진.png'));assert.throws(()=>normalize({schema:2},base),/schema/);});
test('result file may not replace a source, job, output, or embedded image',()=>{const base=path.resolve('jobs'),job={input:'source.hwp',output:'copy.hwp',blocks:[{type:'image',path:'photo.png'}]};for(const name of ['source.hwp','copy.hwp','job.json','photo.png'])assert.throws(()=>resultPath(path.join(base,name),job,base,path.join(base,'job.json')),/결과 JSON/);assert.equal(resultPath(path.join(base,'result.json'),job,base),path.join(base,'result.json'));});
test('concurrent CLI operations on one path fail and lock releases after failure',async()=>{const home=fs.mkdtempSync(path.join(os.tmpdir(),'office-lock-')),file=path.join(home,'doc.hwp');try{await assert.rejects(lock(home,file,async()=>{await assert.rejects(lock(home,file,async()=>{}),/진행 중/);throw new Error('deliberate');}),/deliberate/);assert.equal(await lock(home,file,async()=>42),42);}finally{fs.rmSync(home,{recursive:true,force:true});}});
